// Pet world: a small diorama scene where the GLB pets live together, opened from the tray.
// A floating grass-island stage with primitive props (data-driven so an asset kit can replace them),
// an orbit camera, and the `world` ground/blocking interface the pets query — they never assume
// flat/open ground, so later phases can swap in a heightmap (3rd-person) or voxels (sandbox).
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';
// ⚠️ The ?v= query on module imports = cache buster. The watchdog only ETag-watches world.js; imported modules
// are treated as fresh for days by the browser's heuristic cache and don't refresh even on reconnect (chair not showing, measured —
// 2026-10-23). Bump v here whenever a module is modified. The server no-cache header is the second line of defense.
import { createGlbPetEntity, updateGlbPetEntity, GLB_MOTIONS, GLB_ACCESSORIES, setGlbPetAccessory, makeBffRing, setGlbPetCharm } from './glb-pet-entity.js?v=9';
import { ISLAND_R, ISLANDS, BRIDGES, HILLS, HOUSE, FLAT_SPOTS, PROPS, FERRY_PIERS, FERRY_SEA_POINTS } from './world-layout.js?v=2';
import { kitProp } from './world-kit.js?v=2';

// ---- 🔨 Construction-mode saved layout: overwrite PROPS/HOUSE/FLAT_SPOTS "before" building the scene. Terrain pads,
// bed coordinates, blob shadows and house interior all derive from p.x/z at build time, so changing them here makes
// every builder below bake against the new positions automatically. Saving goes to the server first (/api/world_layout — shared by phone/desktop),
// falling back to localStorage when absent (static server, etc.). id is "type-ordinal" (tree-1, lamp-3…) — new props of the
// same type must be appended at the end of the world-layout.js list so saved layouts don't shift.
const savedLayout = await (async () => {
    try {
        const r = await fetch('/api/world_layout', { signal: AbortSignal.timeout(1500) });
        if (r.ok) {
            const j = await r.json();
            if (j && j.layout && typeof j.layout === 'object') return j.layout;
        }
    } catch (err) {}
    try { return JSON.parse(localStorage.getItem('world-layout')) || {}; } catch (err) { return {}; }
})();
// 🔄 World state KV sync (/api/world_kv — shared by phone/desktop): the server is the source of truth for progress, collections and world state.
// localStorage is per-device, so the codex, shells, unlocks and discoveries diverged per device (user report — same root cause as fruit).
// Kept per-device: world-eco (performance), world-layout (dedicated API), world-fruit-* (dedicated API), world-last-seen (per-device recap).
const WORLD_SYNC_KEYS = ['world-shells', 'world-treasure', 'world-seafood', 'world-fishdex', 'world-acc-unlocked', 'world-pantry', 'world-icebox', 'world-market-used', 'world-recipes-unlocked', 'world-dishes-found', 'world-kitchen-leftover',
    'world-sea-found', 'world-seabed-dug', 'world-islet-dug', 'world-discover', 'world-houselight', 'world-pets',
    'world-season', 'worldLampBrightness', 'world-events', 'world-diary-auto', 'world-mail-read', 'world-space-poi', 'world-moon-dug', 'world-last-seen', 'world-pier-order', 'world-pier-stock', 'world-fishchair-noted', 'world-aurora-said', 'world-proactive-recent', 'world-rings', 'world-meadow-noted', 'world-owner-drafts', 'world-pet-aliases'];   // Shared last-seen = prevents double settlement across devices · fishchair-noted = chair-appearance event shared once
// ⚠️ **Must be declared before the boot loop.** The loop below calls worldSync(k) when it meets a key
// missing on the server; if this const sits below the loop, a TDZ ReferenceError fires and **the whole try aborts**.
// Then every key after that one is never restored — world-events and world-diary-auto sit right
// after it, so event logs diverged per device and the picture diary skipped whole dates (measured).
const worldSyncTimers = {};
function worldSync(key) {   // Only changed keys, 900ms debounced POST — raw strings as-is (schema-agnostic)
    clearTimeout(worldSyncTimers[key]);
    worldSyncTimers[key] = setTimeout(() => {
        let v = null;
        try { v = localStorage.getItem(key); } catch (e) {}
        if (v === null) return;
        fetch('/api/world_kv', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ key, value: v }),
        }).catch(() => {});
    }, 900);
}

try {   // Once at boot — server values overwrite local (the key is running before every reader below)
    const r = await fetch('/api/world_kv', { signal: AbortSignal.timeout(1500) });
    if (r.ok) {
        const kv = (await r.json()).kv || {};
        for (const k of WORLD_SYNC_KEYS) {
            if (typeof kv[k] === 'string') { try { localStorage.setItem(k, kv[k]); } catch (e) {} }
            else worldSync(k);   // Key empty on server = upload this device's value (first-migration seed — without it, the moment a sparse device writes first, the richer one gets overwritten)
        }
    }
} catch (e) { /* Static serving without backend — proceed with local cache */ }
// Movable types (pond = terrain depression so fixed, furniture = derived from the house interior so it follows the house)
const MOVABLE_TYPES = new Set(['tree', 'bowl', 'fence', 'sunbed', 'hammock', 'lamp', 'radio', 'coffee', 'food', 'swing', 'seesaw', 'house', 'monument', 'hugspot', 'pecktree', 'well', 'capsule', 'boulder', 'garden', 'scarecrow', 'compost', 'piano', 'photoboard', 'mailbox', 'gym', 'trampoline', 'vine', 'melonpatch', 'ringnest', 'chickgarden', 'gardenbench', 'fruitbasket', 'library', 'flowerbasket', 'pond', 'portal', 'icebox', 'kitchen', 'bonfire', 'pierboard']);
// Island definition fingerprint — changes whenever an island is moved or resized (regression guard: auto-detects an "island move" in saved layouts).
// 'v2|' prefix = layout renewal generation: even with island geometry unchanged, bumping the prefix resets all satellite-island props
// to the new defaults. The coordinate table (MOVED_DEFAULTS) can't overcome generation drift between per-client copies
// (server file / localStorage origins) — a measured lesson; the forced-reset lever is unified into this one prefix.
const ISLAND_SIG = 'v3|' + ISLANDS.map((i) => `${i.x},${i.z},${i.r}`).join('|');   // v3: swing = north edge, seesaw = SE (user re-swapped)
// Props whose default placement was renewed while the island stayed put: if the saved value is 'exactly the old default', the user
// never touched it, so it follows the new default (covers the fingerprint mechanism's blind spot — the playground island spread-out layout was the first case).
const MOVED_DEFAULTS = {
    'swing-1':  [[11.05, 6.3], [11.59, 6.58], [11.7, 7.6], [13.15, 4.6]],
    'seesaw-1': [[12.17, 4.77], [12.71, 5.05], [13.15, 4.6], [11.7, 7.6]],
    'gym-1':    [[8.62, 6.51], [9.16, 6.79]],
    'lamp-7':   [[9.71, 4.3], [9.35, 5.05]],
    'tree-5':   [[11.19, 3.28]],
    'house-1':  [[2.7, 2.05]],      // Rotation/scale renewal — a saved old rotY must not mask the new default rotY
    'bowl-1':   [[0.95, 1.62]],
    'radio-1':  [[2.2, 0.63], [2.3, 0.35]],
    'tree-3':   [[2.05, 5.2]],
    'coffee-1': [[-3.35, 2.18]],
    'vine-2':   [[-1.9, 1.3]],
    'piano-1':  [[-0.61, 1.95]],
    'photoboard-1': [[-1.95, -0.73]],
    'mailbox-1': [[0.38, 3.9]],
    'tree-7':   [[1.35, -3.5]],
    'pond-1':   [[-2.6, -2.9]],
    'portal-1': [[4.3, -1.5]],
    'lamp-1':   [[1.3, 3.09]],
    'lamp-2':   [[3.34, 0.24]],
    'lamp-3':   [[2.0, -2.68]],
    'lamp-4':   [[-1.05, -3.3]],
    'lamp-5':   [[-3.33, -0.37]],
    'lamp-6':   [[-1.85, 2.79]],
    'fence-1':  [[-5.13, 1.52]],   // Farm island bridge landing — fence shifted south
};
{
    const counts = {};
    // If the saved fingerprint differs from the current one, a satellite island moved/grew — discard that island's props' old saved coordinates and use base.
    const islandsChanged = savedLayout._sig !== ISLAND_SIG;   // undefined (saves from before fingerprints) is also reset — the !== undefined guard was the hole that never let go of ancient saves
    for (const p of PROPS) {
        p.layoutId = `${p.type}-${counts[p.type] = (counts[p.type] || 0) + 1}`;
        p.def = { x: p.x, z: p.z, rotY: p.rotY || 0 };            // Original coordinates for "reset all"
        let o = MOVABLE_TYPES.has(p.type) ? savedLayout[p.layoutId] : null;
        // ① If the island changed and this prop's home island (by base) is a satellite (≥1), discard the old saved value → snap to the base position
        //    (when a whole island moves, old absolute coordinates are meaningless — the base moved along in world-layout.js is the answer)
        if (o && islandsChanged && islandOf(p.def.x, p.def.z) >= 1) { o = null; delete savedLayout[p.layoutId]; }
        // ①.5 Follow default-layout renewal — if the saved value equals the old default (±6cm), discard it and use the new default
        if (o && MOVED_DEFAULTS[p.layoutId] && MOVED_DEFAULTS[p.layoutId].some(([ox, oz]) => Math.hypot(o.x - ox, o.z - oz) < 0.06)) {
            o = null;
            delete savedLayout[p.layoutId];
        }
        // ② If the old saved coordinates are stranded over water, discard and use the new default position — only islandOf (r−0.3 margin) and bridges count as valid land.
        if (o && Number.isFinite(o.x) && Number.isFinite(o.z) && (islandOf(o.x, o.z) >= 0 || onBridge(o.x, o.z))) {
            p.x = o.x; p.z = o.z;
            if (Number.isFinite(o.rotY)) p.rotY = o.rotY;
        }
    }
    // If the fingerprint is missing (first load) or differs, re-save once with the new fingerprint → establishes the baseline for detecting the next island move.
    // (setTimeout: the let/CAR/BOAT that saveLayout references are still in TDZ right now, so defer until after module load)
    if (savedLayout._sig !== ISLAND_SIG) setTimeout(saveLayout, 1500);
    const h = PROPS.find((p) => p.type === 'house');
    if (h) { HOUSE.x = h.x; HOUSE.z = h.z; HOUSE.rotY = h.rotY; } // Sync the anchor for houseWorld/houseBlocked
    // Terrain flattening pad follows its owner prop (the new position becomes flat from the next load)
    for (const s of FLAT_SPOTS) {
        if (!s.follow) continue;
        const p = PROPS.find((q) => q.layoutId === s.follow);
        if (p) { s.x = p.x; s.z = p.z; }
    }
}

const renderer = new THREE.WebGLRenderer({ antialias: true });   // MSAA — near-free on Apple's tile-based GPU, all the AA a single forward pass needs
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));    // full retina again: without the ~19-pass chain, 2x + MSAA costs less than 1.5x did with it
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.shadowMap.autoUpdate = false;   // The shadow map is baked by renderFrame() once every 2 frames (30/15Hz — invisible with soft shadows)
renderer.toneMapping = THREE.ACESFilmicToneMapping;   // gentle filmic rolloff — pastels stay soft
renderer.toneMappingExposure = 1.0;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
// Soft image-based ambient (RoomEnvironment) — gives every standard material a gentle studio
// sheen instead of dead-flat shading. Kept subtle; the sun/hemisphere still carry the scene.
{
    const pmrem = new THREE.PMREMGenerator(renderer);
    scene.userData.envTex = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;   // Referenced directly by foil/glaze materials — their own brightness, decoupled from the global environmentIntensity (0.15)
    scene.environment = scene.userData.envTex;
    scene.environmentIntensity = 0.15;
    pmrem.dispose();
}
// Sky: a vertical gradient painted onto a big inside-out dome (fog is disabled on it so the
// gradient stays crisp), repainted through the day/night cycle below — plus drifting clouds, a
// sun, a moon, and a bed of stars that fades in after dark.
scene.background = new THREE.Color(0xdff1fd);
scene.fog = new THREE.Fog(0xdff1fd, 14, 34);
let camUnderwater = false;   // 🤿 Camera below the water surface — decided by updateUnderwater; the single signal for fog/sky switching
const skyCv = document.createElement('canvas');
skyCv.width = 1; skyCv.height = 256;
const skyCtx = skyCv.getContext('2d');
const skyTex = new THREE.CanvasTexture(skyCv);
let skyDomeMesh = null;   // 🤿 Underwater mode hides it briefly
{
    const sky = new THREE.Mesh(
        new THREE.SphereGeometry(42, 32, 24),
        // toneMapped:false — stops ACES from desaturating/greying the sky too (game skybox standard).
        // The palette hex shows on screen as-is, so the SKY_* colors are the final colors.
        new THREE.MeshBasicMaterial({ map: skyTex, side: THREE.BackSide, fog: false, depthWrite: false, toneMapped: false })
    );
    scene.add(sky);
    skyDomeMesh = sky;
}
// Sun & moon share one east→west arc (rise 6:00 / set 18:00 — the moon takes the night shift); both
// ignore fog so they glow through the haze. Stars sit on the upper dome, opacity driven at night.
const sunMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.95, 20, 16),
    new THREE.MeshBasicMaterial({ color: 0xffd75e, fog: false, toneMapped: false })   // Same reason as the sky — keeps the vivid yellow
);
scene.add(sunMesh);
const moonMesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.75, 20, 16),
    new THREE.MeshBasicMaterial({ color: 0xf2eede, fog: false, toneMapped: false })
);
scene.add(moonMesh);
let starMat = null, starPts = null;
{
    // Fixed-seed starfield — for saved constellations (㉞) to stay valid across boots, the stars must always rise in the same spots.
    let starSeed = 20260707;
    const srand = () => { starSeed = (starSeed * 1664525 + 1013904223) >>> 0; return starSeed / 4294967296; };
    const pts = [];
    for (let i = 0; i < 240; i++) {
        const u = srand() * 2 - 1, a = srand() * Math.PI * 2;
        const v = new THREE.Vector3(Math.sqrt(1 - u * u) * Math.cos(a), u, Math.sqrt(1 - u * u) * Math.sin(a));
        v.y = Math.abs(v.y) * 0.9 + 0.08;       // upper hemisphere only
        v.normalize().multiplyScalar(39);
        pts.push(v.x, v.y, v.z);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.28, transparent: true, opacity: 0, fog: false, depthWrite: false });
    starPts = new THREE.Points(g, starMat);
    scene.add(starPts);
}
// 🌌 Atmosphere veil: glowing ring disc at y8.5 — seen from space, the archipelago shows through a thin atmosphere layer
// and a planetary rim glow wraps the world's edge (visual proof of "we're outside the atmosphere"). Driven by updateSpaceSky.
const atmoVeilMat = (() => {
    const cv = document.createElement('canvas');
    cv.width = cv.height = 256;
    const c = cv.getContext('2d');
    const g = c.createRadialGradient(128, 128, 0, 128, 128, 128);
    g.addColorStop(0, 'rgba(158,216,240,0)');
    g.addColorStop(0.5, 'rgba(158,216,240,0.03)');
    g.addColorStop(0.74, 'rgba(150,214,244,0.2)');
    g.addColorStop(0.86, 'rgba(190,232,255,0.46)');
    g.addColorStop(0.94, 'rgba(190,232,255,0.18)');
    g.addColorStop(1, 'rgba(190,232,255,0)');
    c.fillStyle = g;
    c.fillRect(0, 0, 256, 256);
    return new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(cv), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, fog: false, toneMapped: false, side: THREE.DoubleSide });
})();
const atmoVeil = new THREE.Mesh(new THREE.CircleGeometry(40, 48).rotateX(-Math.PI / 2), atmoVeilMat);
atmoVeil.position.y = 8.5;
atmoVeil.visible = false;
scene.add(atmoVeil);
// 🌌 Milky Way band: tilted cylinder strip inside the dome + canvas bake (light clusters + fine stars; seam handled by wrap draw).
// Strong in space (0.42), subtle on a clear deep night on the ground (~0.13) — synergy with constellation play.
const milkyMat = (() => {
    const cv = document.createElement('canvas');
    cv.width = 512; cv.height = 128;
    const c = cv.getContext('2d');
    let seed = 20260721;
    const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
    for (let i = 0; i < 70; i++) {
        const x = rnd() * 512, y = 64 + (rnd() + rnd() - 1) * 34, r = 14 + rnd() * 30;
        const col = rnd() < 0.3 ? '255,226,200' : '205,220,255';
        for (const ox of [-512, 0, 512]) {   // Horizontal tiling — prevents the cylinder wrap seam
            const gg = c.createRadialGradient(x + ox, y, 0, x + ox, y, r);
            gg.addColorStop(0, `rgba(${col},0.095)`);
            gg.addColorStop(1, `rgba(${col},0)`);
            c.fillStyle = gg;
            c.beginPath(); c.arc(x + ox, y, r, 0, Math.PI * 2); c.fill();
        }
    }
    for (let i = 0; i < 110; i++) {
        const x = rnd() * 512, y = 64 + (rnd() + rnd() - 1) * 40;
        c.fillStyle = `rgba(240,246,255,${0.25 + rnd() * 0.5})`;
        c.fillRect(x, y, 1.3, 1.3);
    }
    return new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(cv), side: THREE.BackSide, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, fog: false, toneMapped: false });
})();
const milkyMesh = new THREE.Mesh(new THREE.CylinderGeometry(38.2, 38.2, 15, 48, 1, true), milkyMat);
milkyMesh.rotation.set(0.1, 0.9, 0.62);   // A band crossing the sky diagonally
milkyMesh.visible = false;
scene.add(milkyMesh);
// Constellation (㉞) render state — updateDayNight fades it together with the stars, so declared here (before the first call).
const constelLineMat = new THREE.LineBasicMaterial({ color: 0x9fd8ff, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false });
const constelObjs = [];   // { line, label }
const cloudSpin = new THREE.Group();     // rotated a hair every frame → clouds drift
scene.add(cloudSpin);
const cloudMat = new THREE.MeshLambertMaterial({ color: 0xffffff, emissive: 0xaecbe8, emissiveIntensity: 0.35 });
let seaMat = null;           // assigned when the ocean is built below; day/night tints it
const foamRings = [];        // lapping foam meshes around the cliff
// Streetlamps: filled with the stage; glow ramps up through dusk, scaled by the 💡 slider.
const lamps = [];            // { light: PointLight }
const lampGlobeMat = new THREE.MeshLambertMaterial({ color: 0xfff1cf, emissive: 0xffc978, emissiveIntensity: 0 });
let lampBrightness = 0.6;
try {
    const saved = parseFloat(localStorage.getItem('worldLampBrightness'));
    if (!Number.isNaN(saved)) lampBrightness = THREE.MathUtils.clamp(saved, 0, 1);
} catch (e) {}
{
    const defs = [
        { a: 0.3, r: 11,   y: 4.6, s: 1.0 },
        { a: 1.9, r: 13,   y: 5.6, s: 1.35 },
        { a: 3.6, r: 10,   y: 4.1, s: 0.8 },
        { a: 5.1, r: 12.5, y: 5.1, s: 1.1 },
    ];
    // All 20 lobes share one material, so merge into a single geometry — draw calls 20→1, identical shape.
    // (Transforms baked into the geometry: lobe squash → lobe position → cloud scale → cloud position —
    //  the same order the old group hierarchy produced.)
    const geos = [];
    for (const d of defs) {
        for (const [lx, ly, lz, lr] of [[0, 0, 0, 0.55], [0.5, 0.08, 0.1, 0.4], [-0.48, 0.05, -0.08, 0.42], [0.15, 0.3, 0, 0.35], [-0.2, 0.26, 0.12, 0.3]]) {
            const lobe = new THREE.SphereGeometry(lr, 18, 14);
            lobe.scale(1, 0.62, 1);           // squash into that puffy-flat cartoon cloud shape
            lobe.translate(lx, ly, lz);
            lobe.scale(d.s, d.s, d.s);
            lobe.translate(Math.cos(d.a) * d.r, d.y, Math.sin(d.a) * d.r);
            geos.push(lobe);
        }
    }
    const clouds = new THREE.Mesh(mergeGeometries(geos), cloudMat);
    clouds.matrixAutoUpdate = false;   // Only the parent (cloudSpin) rotates — local transform stays identity forever
    cloudSpin.add(clouds);
}

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 3.0, 8.2);
camera.lookAt(0, 0.4, 0);

// ---- Game-style shading (no post chain): the old GTAO→bloom→SMAA composer re-rendered
// the scene a second time for normals and pushed ~19 fullscreen half-float passes per frame — the
// most expensive possible shape on Apple's tile-based GPUs. Production playbook instead: bake what
// never moves, fake what's cheap to fake. Contact shading became load-time blob shadows (see the
// PROPS loop); halos are additive glow sprites below; AA is canvas MSAA; ACES tone mapping already
// lives on the renderer. One forward render per frame, storybook look intact. ----
const glowTex = (() => {
    const cv = document.createElement('canvas');
    cv.width = cv.height = 128;
    const ctx = cv.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0, 'rgba(255,255,255,0.85)');
    g.addColorStop(0.4, 'rgba(255,255,255,0.28)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 128, 128);
    return new THREE.CanvasTexture(cv);
})();
function glowSprite(color, size, opacity) {
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({
        map: glowTex, color, opacity, transparent: true,
        blending: THREE.AdditiveBlending, depthWrite: false, fog: false,
    }));
    sp.scale.setScalar(size);
    return sp;
}
const sunGlow = glowSprite(0xffdf8a, 5.2, 0.75);   // the warm halo the bloom pass used to paint
sunMesh.add(sunGlow);
moonMesh.add(glowSprite(0xbcd2ff, 3.2, 0.5));

// 📱 Touch device detection: used only for "screen layout" things like UI size, virtual joystick visibility and power-save defaults. Input
// branching uses each event's pointerType instead of this flag, so mouse behavior is preserved as-is
// even on touchscreen laptops.
const IS_TOUCH = (window.matchMedia && matchMedia('(pointer: coarse)').matches) || navigator.maxTouchPoints > 0;

// ⚠️ Error visibility: the console isn't visible on the phone, so script errors are shown as a toast and sent to the server log
// (/api/world_log → USER_DATA_DIR/world/client-errors.log). Same-message spam is suppressed.
let lastErrAt = 0, lastErrMsg = '';
function reportClientError(msg) {
    try {
        const m = String(msg || '').slice(0, 300);
        if (!m || (m === lastErrMsg && Date.now() - lastErrAt < 30000)) return;
        lastErrAt = Date.now(); lastErrMsg = m;
        try { showToast(`⚠️ 오류가 났어요: ${m.slice(0, 80)}`); } catch (e) {}
        fetch('/api/world_log', {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ msg: m, ua: navigator.userAgent }),
        }).catch(() => {});
    } catch (e) {}
}
window.addEventListener('error', (e) => reportClientError(e.message || e.error));
window.addEventListener('unhandledrejection', (e) => reportClientError(e.reason && (e.reason.message || e.reason)));

// ♡ laptop-friendly pacing: one forward pass is already cheap, so power-save is now about *when* we
// draw, not how. Watched + plugged in → 60fps at full retina; window unfocused (the world usually
// sits beside real work) → 15fps; ⚡ eco (persisted) or on battery → 30fps at 1.5x pixels.
// See frameIntervalMs() for all tiers — focused spectating 30fps, 60s+ spectating/unfocused 15fps.
// 📱 Phone/tablet default to power-save (30fps·1.5x — heat/battery). If the user explicitly turned it off with the ⚡ button,
// '0' remains in localStorage, so respect that choice.
const savedEco = localStorage.getItem('world-eco');
