            const tone = 0.86 + R() * 0.3;
            ctx.fillStyle = `rgb(${Math.round(201 * tone)},${Math.round(120 * tone)},${Math.round(105 * tone)})`;
            ctx.fillRect(x + s / 42, r * bh + s / 42, bw - s / 21, bh - s / 21);
