const gradMat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.95, metalness: 0 });
const gradMatWood = new THREE.MeshStandardMaterial({ vertexColors: true, map: woodTex, roughness: 0.95, metalness: 0 });
