function makeRadio() {
    // Retro radio remodel (Animal Crossing grammar): two-tone body + cream face panel + horizontal grille slats +
    // amber dial window (red needle) + 2 knobs + leather handle + chrome antenna. Static, so a merge candidate.
    const g = new THREE.Group();
    const stand = new THREE.Mesh(new RoundedBoxGeometry(0.3, 0.03, 0.16, 3, 0.012), M(0xb08a60, { map: woodTex }));
    stand.position.y = 0.015;
    g.add(stand);
    const body = GM(new RoundedBoxGeometry(0.27, 0.17, 0.115, 3, 0.035), 0xf2907e, 0xc95f52);   // Coral two-tone
    body.position.y = 0.125;
    g.add(body);
    const face = GM(new RoundedBoxGeometry(0.23, 0.125, 0.02, 2, 0.01), 0xfff3dd, 0xe8d4b2);   // Cream face panel
    face.position.set(0, 0.125, 0.052);
    g.add(face);
    const grille = new THREE.Mesh(new RoundedBoxGeometry(0.105, 0.095, 0.012, 2, 0.008), M(0x6a564c));   // Grille base
    grille.position.set(-0.048, 0.125, 0.062);
    g.add(grille);
    for (let i = 0; i < 4; i++) {   // Horizontal slats — signature of a retro speaker
        const slat = new THREE.Mesh(new THREE.BoxGeometry(0.088, 0.008, 0.008), M(0xfff3dd));
        slat.position.set(-0.048, 0.093 + i * 0.021, 0.068);
        g.add(slat);
    }
    const dial = new THREE.Mesh(new RoundedBoxGeometry(0.075, 0.045, 0.012, 2, 0.006), M(0xffd98a, { emissive: 0xcf9c40, emissiveIntensity: 0.35 }));   // Amber dial window
    dial.position.set(0.055, 0.155, 0.062);
    g.add(dial);
    const needle = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.036, 0.006), M(0xd8503c));
    needle.position.set(0.065, 0.155, 0.068);
    g.add(needle);
    const knobMat = M(0xfff1cf);
    for (const kx of [0.032, 0.082]) {   // 2 knobs — below the dial
        const knob = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.017, 0.02, 12), knobMat);
        knob.rotation.x = Math.PI / 2;
        knob.position.set(kx, 0.093, 0.062);
        g.add(knob);
        const notch = new THREE.Mesh(new THREE.BoxGeometry(0.004, 0.012, 0.006), M(0x8a6a52));
        notch.position.set(kx, 0.097, 0.072);
        g.add(notch);
    }
    const handle = new THREE.Mesh(new THREE.TorusGeometry(0.055, 0.011, 8, 16, Math.PI), M(0x8a5c40));   // Leather handle
    handle.position.set(0, 0.21, 0);
    g.add(handle);
    for (const hx of [-0.055, 0.055]) {
        const lug = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.014, 0.018, 8), M(0x8a5c40));
        lug.position.set(hx, 0.208, 0);
        g.add(lug);
    }
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.007, 0.26, 6), M(0x9aa8b5));   // Chrome antenna
    antenna.position.set(-0.1, 0.3, -0.03);
    antenna.rotation.z = 0.48;
    g.add(antenna);
    const tip = new THREE.Mesh(new THREE.SphereGeometry(0.012, 8, 6), M(0x9aa8b5));
    tip.position.set(-0.16, 0.415, -0.03);
    g.add(tip);
    return g;
}

// 🍳 Outdoor kitchen v2 — silver island (user-approved redesign): a freestanding counter with stainless top + charcoal body,
