    const g = new THREE.Group();
    const frame = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.05, 10, 28), M(0x8fd0b8));
    frame.rotation.x = Math.PI / 2;
    frame.position.y = 0.26;
