    for (const [id, n] of Object.entries(pantryCounts)) if (n > 0) { const c = GARDEN_CROPS.find((q) => q.id === id); out.push({ src: 'pantry', id, ko: c ? c.ko : id, emoji: c ? c.emoji : '🥬', n }); }
