function startEternScene(chef) {
    const friend = pets.find((q) => q !== chef);
    if (!friend) { if (chef !== possessed) releaseAI(chef, 2); return; }
    friend.pet.sleeping = false;
    friend.pet.autoSleeping = false;
    if (friend.bed) forceEndBed(friend);
    if (friend.dip) endDip(friend);
    if (aiFishing && aiFishing.p === friend) endAiFishing();
    releaseAI(friend);
    (async () => {
        await gotoAsync(friend, chef.mover.position.x + 0.55, chef.mover.position.z + 0.15);
        if (friend.ai.state !== 'player') friend.ai.state = 'busy';
        giveFood(friend, { id: 'cloche', name: '영원 케이크 (반쪽)' }, '주방에서');
        chef.mover.rotation.y = Math.atan2(friend.mover.position.x - chef.mover.position.x, friend.mover.position.z - chef.mover.position.z);
        friend.mover.rotation.y = chef.mover.rotation.y + Math.PI;
        eternScene = { chef, friend, t: 0, hearts: false };
    })();
}
function updateEternScene(delta) {
    if (!eternScene) return;
    const { chef, friend } = eternScene;
    eternScene.t += delta;
    for (const q of [chef, friend]) {   // Auto nom-nom — keeps the sequence going until it's all eaten
        if (q.food && !q.food.seq && eternScene.t > 0.8) q.food.seq = { count: 3, t: 0, played: -1 };
    }
    if (!eternScene.hearts && eternScene.t > 1.6) {
        eternScene.hearts = true;
        const mx = (chef.mover.position.x + friend.mover.position.x) / 2;
        const mz = (chef.mover.position.z + friend.mover.position.z) / 2;
        for (let i = 0; i < 10; i++) {
            const spr = glowSprite(0xf2a5c0, 0.07 + Math.random() * 0.05, 0.9);
            spr.position.set(mx + (Math.random() - 0.5) * 0.5, chef.height * 0.7 + chef.mover.position.y, mz + (Math.random() - 0.5) * 0.5);
            scene.add(spr);
            hugBurst.push({ spr, vx: (Math.random() - 0.5) * 0.25, vy: 0.55 + Math.random() * 0.3, vz: (Math.random() - 0.5) * 0.25, t: 0.8 });
        }
        logWorldEvent('둘이 영원 케이크를 나눠 먹었다 — 영원히 베프 🎂💗');
        maybeProactive(null, '방금 절친과 영원 케이크를 나눠 먹었다! 우리는 영원히 베프다!');
    }
    if ((!chef.food && !friend.food) || eternScene.t > 30) {
        if (friend.ai.state === 'busy') releaseAI(friend, 1.5);
        if (chef !== possessed && chef.ai.state === 'busy') releaseAI(chef, 1.5);
        eternScene = null;
    }
}
function updateCooking(delta) {
    if (!cooking) return;
    const { p, r } = cooking;
    if (cooking.phase === 'walk') {
        if (p === possessed || p.ai.state !== 'goto') { if (cooking.p === p && p.ai.state === 'goto') releaseAI(p); cooking = null; }
        return;
    }
    if (p !== possessed && p.ai.state !== 'busy') { endCookFx(); cooking = null; return; }   // Director steal — return it
    cooking.t += delta;
    if (cookFx) {   // Ingredient pellets bouncing on the board (simple parabola)
        for (const bd of cookFx.beads) {
            if (bd.userData.vy) {
                bd.position.y += bd.userData.vy * delta;
                bd.userData.vy -= 3.4 * delta;
                if (bd.position.y <= 0.545) { bd.position.y = 0.545; bd.userData.vy = 0; }
            }
        }
    }
    if (cooking.phase === 'chop') {
        if (cooking.t - cooking.act > 0.75) {
            cooking.act = cooking.t;
            if (!p.pet.action) p.pet.action = { id: 'dig', t: 0 };
            playBuffer(munchBuf, { vol: 0.42, rate: 0.5 + Math.random() * 0.14, filterFreq: 640 });   // Board chop-chop
            if (cookFx) for (const bd of cookFx.beads) bd.userData.vy = 0.55 + Math.random() * 0.35;
        }
        if (cooking.t > 2.3) { cooking.phase = 'wok'; cooking.t = 0; cooking.act = 0; if (cookFx) cookFx.pan.visible = true; }
        return;
    }
    if (cooking.phase === 'wok') {
        if (cookFx) {
            cookFx.pan.position.y = 0.56 + Math.abs(Math.sin(cooking.t * 7)) * 0.045;
            cookFx.pan.rotation.z = Math.sin(cooking.t * 7) * 0.22;
        }
        if (cooking.t - cooking.act > 0.9) {
            cooking.act = cooking.t;
            if (!p.pet.action) p.pet.action = { id: 'dance', t: 0 };
            playBuffer(swishBuf, { vol: 0.34, rate: 1.35 + Math.random() * 0.3, filterFreq: 2600 });   // Sizzle
            puffSteam(0);
        }
        if (cooking.t > 3.0) { cooking.phase = 'plate'; cooking.t = 0; puffSteam(2); }
        return;
    }
    if (cooking.t > 1.3 && cooking.exp) {   // 🧪 Experiment plating — discovery or unidentified
        endCookFx();
        const res = cooking.expResult;
        const chef = p;
        if (res) {
            const first = !recipesUnlocked[res.id];
            recipesUnlocked[res.id] = true;
            saveRecipesUnlocked();
            dishesFound[res.id] = (dishesFound[res.id] || 0) + 1;
            try { localStorage.setItem('world-dishes-found', JSON.stringify(dishesFound)); worldSync('world-dishes-found'); } catch (e) {}
            giveFood(chef, dishDef(res.id, res.ko), '주방에서');
            if (!chef.pet.action) chef.pet.action = { id: 'happy', t: 0 };
            if (first) {
                fishFanfare();
                showToast(`🧪✨ 새 레시피 발견 — ${res.ko}! 레시피북에 등록됐어요`);
                logWorldEvent(`실험으로 ${res.ko} 레시피를 발견했다 🧪✨`);
                maybeProactive(null, `방금 요리 실험으로 ${res.ko}를 발견했다! 천재적인 조합이었다!`);
            } else logWorldEvent(`${petKo(chef)}가 실험 재현으로 ${res.ko}를 만들었다 🧪`);
            maybeUnlockHearts();
        } else {
            dishesFound.burnt = (dishesFound.burnt || 0) + 1;
            try { localStorage.setItem('world-dishes-found', JSON.stringify(dishesFound)); worldSync('world-dishes-found'); } catch (e) {}
            puffSteam(3, 0x3f3b38);   // Burnt smoke puff
            giveFood(chef, { id: 'cloche', name: '정체불명 요리', burnt: true }, '주방에서');
            if (!chef.pet.action) chef.pet.action = { id: 'think', t: 0 };
            showToast(`💨 퍽! …정체불명 요리가 되어버렸다 (${dishesFound.burnt}번째)`);
            logWorldEvent(`${petKo(chef)}의 실험이 정체불명 요리로 끝났다 💨`);
        }
        refreshKitchenPanel();
        cooking = null;
        if (chef !== possessed) releaseAI(chef, 2);
        return;
    }
    if (cooking.t > 1.3) {   // Plating — cloche pop + codex + fanfare (first dish)
        endCookFx();
        const first = !dishesFound[r.id];
        dishesFound[r.id] = (dishesFound[r.id] || 0) + 1;
        try { localStorage.setItem('world-dishes-found', JSON.stringify(dishesFound)); worldSync('world-dishes-found'); } catch (e) {}
        giveFood(p, dishDef(r.id, r.id === 'eterncake' ? '영원 케이크 (반쪽)' : r.ko), '주방에서');
        if (!p.pet.action) p.pet.action = { id: 'happy', t: 0 };
        if (cooking.meal) {
            const mh = +String(cooking.meal).split('-')[1];
            logWorldEvent(`${petKo(p)}가 ${mh === 8 ? '아침' : mh === 12 ? '점심' : '저녁'}으로 직접 만든 ${r.ko}를 차렸다 🍳${first ? ' — 첫 요리!' : ''}`);
        } else logWorldEvent(`${petKo(p)}가 ${r.ko}를 완성했다 🍳${first ? ' — 첫 요리!' : ''}`);
        if (first) {
            fishFanfare();
            showToast(`🍳✨ 새 요리 발견 — ${r.ko}!`);
            maybeProactive(null, `방금 주방에서 처음으로 ${r.ko}를 만들었다! 뿌듯하다!`);
        }
        maybeUnlockHearts();
        refreshKitchenPanel();
        const chef = p;
        const intent = cooking.intent;
        cooking = null;
        if (r.id === 'eterncake') startEternScene(chef);   // 🎂 A dish shared by two — summon the bestie
        else if (intent && chef !== possessed) startAiCookPost(chef, intent, r);   // Autonomous chef — eat or serve
        else if (chef !== possessed) releaseAI(chef, 2);
    }
}
function toggleKitchenPanel() {
    if (!kitchenPanel) {
        kitchenPanel = document.createElement('div');
        kitchenPanel.style.cssText = 'position:fixed; right:64px; bottom:calc(70px + env(safe-area-inset-bottom, 0px)); display:none; width:min(292px, calc(100vw - 90px)); max-height:62vh; overflow-y:auto; background:rgba(30,32,40,0.94); border-radius:12px; padding:10px; z-index:110; box-shadow:0 6px 24px rgba(0,0,0,0.4); font-family:sans-serif; color:#fff;';
        kitchenPanel.innerHTML = `<div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:6px;"><span style="font-size:13px; font-weight:700;">🍳 야외 주방</span><span style="display:flex; gap:4px; align-items:center;"><span class="kc-labbtn" title="요리 실험" style="font-size:14px; cursor:pointer; padding:2px 7px; border-radius:7px;">🧪</span><span class="kc-x" style="color:#aab; font-size:13px; cursor:pointer; padding:2px 6px;">✕</span></span></div>
<div class="kc-stock" style="font-size:11.5px; opacity:0.9; background:rgba(255,255,255,0.06); border-radius:8px; padding:6px 8px; margin-bottom:8px; line-height:1.4;"></div>
<div class="kc-body" style="display:grid; grid-template-columns:repeat(4, 1fr); gap:7px;"></div>
<div class="kc-lab" style="display:none;"></div>`;
        kitchenPanel.addEventListener('pointerdown', (e) => e.stopPropagation());
        kitchenPanel.querySelector('.kc-x').onclick = () => { kitchenPanel.style.display = 'none'; };
        kitchenPanel.querySelector('.kc-labbtn').onclick = () => { kitchenView = kitchenView === 'lab' ? 'recipes' : 'lab'; refreshKitchenPanel(); };
        document.body.appendChild(kitchenPanel);
    }
    kitchenPanel.style.display = (kitchenPanel.style.display === 'none' || !kitchenPanel.style.display) ? 'block' : 'none';
    if (kitchenPanel.style.display !== 'none') refreshKitchenPanel();
}
// 8 beds (2×4) — the first 4 keep the old saved index positions (compat); 5th~8th are the left/right wing beds.
const GARDEN_PLOTS_LOCAL = [[-0.32, -0.21], [0.32, -0.21], [-0.32, 0.26], [0.32, 0.26], [-0.96, -0.21], [0.96, -0.21], [-0.96, 0.26], [0.96, 0.26]];
let gardenPlots = GARDEN_PLOTS_LOCAL.map(() => null);   // { kind, plantedAt, boost, wateredStage } | null
let gardenGroups = null;
let gardenStageHash = '';
function gardenStage(pl) {   // 0 empty bed, 1 seed, 2 sprout, 3 harvestable
    if (!pl) return 0;
    const el = Date.now() - pl.plantedAt + (pl.boost || 0);
    return el >= GARDEN_T1 + GARDEN_T2 ? 3 : el >= GARDEN_T1 ? 2 : 1;
}
function buildPlotVisual(stage, kind) {
    const v = new THREE.Group();
    if (stage === 1) {
        const mound = new THREE.Mesh(new THREE.SphereGeometry(0.085, 10, 8), M(0x7d5c38));
        mound.scale.y = 0.5;
        v.add(mound);
    } else if (stage === 2) {
        const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.02, 0.11, 6), M(0x4e9a3d));
        stem.position.y = 0.055;
        v.add(stem);
        for (const s of [-1, 1]) {
            const leaf = new THREE.Mesh(new THREE.SphereGeometry(0.038, 8, 6), M(0x66bb4a));
            leaf.position.set(s * 0.04, 0.11, 0);
            leaf.scale.set(1, 0.5, 0.6);
            v.add(leaf);
        }
    } else if (stage === 3) {
        if (kind === 'carrot') {
            const top = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.09, 8), M(0xf28034));
            top.position.y = 0.035;
            v.add(top);
            for (const a of [0, 2.1, 4.2]) {
                const frond = new THREE.Mesh(new THREE.ConeGeometry(0.025, 0.12, 6), M(0x4e9a3d));
                frond.position.set(Math.sin(a) * 0.03, 0.13, Math.cos(a) * 0.03);
                frond.rotation.set(Math.cos(a) * 0.35, 0, -Math.sin(a) * 0.35);
                v.add(frond);
            }
        } else if (kind === 'tomato') {
            const bush = new THREE.Mesh(new THREE.SphereGeometry(0.11, 10, 8), M(0x4d9a44));
            bush.position.y = 0.1;
            v.add(bush);
            for (const [x, y, z] of [[0.07, 0.13, 0.05], [-0.06, 0.09, 0.08], [0.02, 0.16, -0.06]]) {
                const t = new THREE.Mesh(new THREE.SphereGeometry(0.032, 8, 6), M(0xe64a3c));
                t.position.set(x, y, z);
                v.add(t);
            }
        } else {
            const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.022, 0.26, 6), M(0x4e9a3d));
            stem.position.y = 0.13;
            v.add(stem);
            const petals = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.085, 0.02, 12), M(0xf2c53d));
            petals.position.y = 0.27;
            petals.rotation.x = 0.5;
            v.add(petals);
            const core = new THREE.Mesh(new THREE.SphereGeometry(0.042, 10, 8), M(0x6f5030));
            core.position.set(0, 0.275, 0.012);
            v.add(core);
        }
    }
    return v;
}
function refreshGardenVisuals() {
    if (!gardenGroups) return;
    gardenGroups.forEach((pg, i) => {
        for (let c = pg.children.length - 1; c >= 0; c--) {
            const ch = pg.children[c];
            pg.remove(ch);
            ch.traverse((o) => { if (o.geometry) o.geometry.dispose(); });
        }
        const st = gardenStage(gardenPlots[i]);
        if (st > 0) pg.add(buildPlotVisual(st, gardenPlots[i].kind));
    });
    gardenStageHash = gardenPlots.map((pl) => gardenStage(pl)).join('');
}
// 🧍‍🌾 Scarecrow — farm island sentinel: post + arm bar, straw head with straw hat, baggy shirt panel. Static, 1 merge.
