const autumnLeafPts = precipPoints(320, leafFallTex, 0.06, 0.45, 0.85, 0.55);   // Autumn only — applySeason turns it on
seasonFall.push({ pts: autumnLeafPts, when: 'autumn' });
applySeason(season, false);   // Paint the boot season immediately (effectively a no-op in summer)
const snowPts = precipPoints(850, snowTex, 0.075, 0.55, 1.05, 0.4);

// Rainbow: a half ring standing in the sea behind the island; UVs rewritten radially so
