    ferrySummon: () => { summonFerryFriend(); return !!ferryHop; },
    callFriend: () => { startPhoneCall(); return !!phoneCall; },
    shellState: () => ({ alive: shells.length, spots: shells.map((sh) => ({ t: sh.t.id, x: +sh.x.toFixed(2), z: +sh.z.toFixed(2), il: sh.islet || null })), counts: shellCounts() }),
    shellSpawn: () => trySpawnShell(true),
    shellPickNearest: () => { const sh = nearestShell(0.85); if (sh) { pickShell(sh); return true; } return false; },   // E2E — bypass the sand island ⌘ preemption zones (palm, plane, sand play); approach+pickup path unchanged
    shellDiag: () => {   // Spawn ring availability breakdown — for placement tuning
        const SAND = ISLANDS[4];
        const out = { ok: 0, wet: 0, plane: 0, blockers: {}, shellsNow: shells.length, nextAt: Math.round(shellNextAt) };
        for (let i = 0; i < 4000; i++) {
            const a = Math.random() * Math.PI * 2;
            const d = 0.9 + Math.random() * 1.05;
            const x = SAND.x + Math.sin(a) * d, z = SAND.z + Math.cos(a) * d;
            if (terrainHeight(x, z) < -0.3) { out.wet++; continue; }
            if (Math.hypot(x - PLANE.x, z - PLANE.z) < 1.3) { out.plane++; continue; }
            let hit = null;
            for (const q of PROPS) { if (q.r > 0 && Math.hypot(x - q.x, z - q.z) < q.r + 0.35) { hit = q; break; } }
            if (hit) { const k = hit.layoutId || hit.kind || 'prop?'; out.blockers[k] = (out.blockers[k] || 0) + 1; continue; }
            out.ok++;
        }
        return out;
    },
    stream: () => ({ loaded: isletChunks.size, islands: ISLANDS.length, queue: isletQueue.length, found: discoveredIslets.size }),
    mapToggle: () => { toggleWorldMap(); return mapOpen; },
    recall: (t) => recallVehicle(t),
    autoReturn: () => { checkAutoReturn(true); return window.__worldDev.vehicles(); },
    streamScan: (x, z, rad) => {   // Pure scan — deserted islet coords are known even before load (E2E)
        const out = [];
        for (let cx = Math.floor((x - rad) / CHUNK); cx <= Math.floor((x + rad) / CHUNK); cx++) {
            for (let cz = Math.floor((z - rad) / CHUNK); cz <= Math.floor((z + rad) / CHUNK); cz++) {
                const il = isletFor(cx, cz);
                if (il && Math.hypot(il.x - x, il.z - z) <= rad) out.push({ key: il.key, x: il.x, z: il.z, r: il.r, name: il.name, kind: il.kind || 'grass', theme: il.theme, treasure: !!il.treasure });
            }
        }
        return out;
    },
    trampState: () => {
        const t = trampInfo();
        return {
            x: t ? +t.x.toFixed(2) : null, z: t ? +t.z.toFixed(2) : null, matY: t ? +t.y.toFixed(2) : null,
            pets: pets.filter((q) => q.tramp).map((q) => ({ n: q.name, y: +q.mover.position.y.toFixed(2), vy: +q.tramp.vy.toFixed(2), b: q.tramp.bounces, flip: !!q.tramp.flip })),
            ai: aiTramp ? { n: aiTramp.p.name, began: aiTramp.began, left: aiTramp.bouncesLeft } : null,
            flips: trampStats.flips, stars: trampStats.stars || 0, doubles: trampStats.doubles,
        };
    },
    trampGo: (name) => startAiTramp(pets.find((q) => q.name === (name || 'puppy'))),
    house: (x, z) => ({ floor: houseFloorY(x, z), blocked: houseBlocked(x, z) }),   // House walking E2E
    houseW: (lx, lz) => houseWorld(lx, lz),
    roofState: () => ({ k: +roofFadeK.toFixed(2) }),
    houseLight: (toggle) => { if (toggle) toggleHouseLight(); return { on: houseLightOn, manual: houseLightManual, parented: !!(HOUSE_DERIVED.light && HOUSE_DERIVED.light.parent) }; },
    roofDiag2: () => {   // Search the whole scene for cones — find the opaque roof copy
        const out = [];
        scene.traverse((o) => {
            if (o.isMesh && o.geometry && o.geometry.type === 'ConeGeometry' && o.geometry.parameters && o.geometry.parameters.radius > 2) {
                out.push({ vis: o.visible, op: o.material.opacity, tr: !!o.material.transparent, tag: !!(o.userData && o.userData.roofFade), parent: o.parent === scene ? 'scene' : (o.parent && o.parent.type) });
            }
        });
        return out;
    },
    roofDiag: () => {
        const pr = PROPS.find((q) => q.type === 'house');
        const list = pr && pr.obj && pr.obj.userData.roofFade;
        return list ? list.map((m) => ({ vis: m.visible, op: +m.material.opacity.toFixed(2), tr: m.material.transparent, inGroup: !!m.parent, geo: m.geometry.type })) : null;
    },
    fruitState: () => ({
        bearing: fruitBearing.map((e) => ({ id: e.pr.layoutId, t: e.type, x: +e.pr.x.toFixed(2), z: +e.pr.z.toFixed(2), hanging: e.group && e.anchors ? e.anchors.length : 0 })),
        ground: groundFruits.map((g) => ({ t: g.type, x: +g.x.toFixed(2), z: +g.z.toFixed(2), settled: g.settled, age: g.at ? Date.now() - g.at : 0, wilting: g.wilting !== undefined })),
        held: possessed && possessed.food && possessed.food.def ? possessed.food.def.fruit || 'food' : null,
        basket: { ...basketCounts },
    }),
    fruitHarvest: (id) => { const e = fruitBearing.find((q) => q.pr.layoutId === id); if (e) harvestFruit(e, possessed); return !!(e && e.shakeT); },
    fruitEat: () => { const f = possessed && possessed.food; if (f && !f.seq) f.seq = { count: 3, t: 0, played: -1 }; return !!f; },
    fruitGive: (t) => { if (possessed) giveFruit(possessed, t || 'apple'); return !!(possessed && possessed.food); },
    fruitThrowNow: () => { startFruitThrow(); return fruitThrows.length; },
