// After 10pm, once a day, both pets write that day's diary side by side (called by animate).
// If the window was closed before 22:00, write it as carry-over for yesterday's date on next open — filled in the morning even if the app was off at night.
// The "written day" flag is consumed only when actually written: previously the flag was set before the check, so opening right after 22:00
// before GLB loading finished meant that day's diary was never written (never consume before success is confirmed).
let diaryAutoAt = 0;   // Next check time — avoids per-frame scanning + failure backoff
// 💬 Owner diary comment — timing: first 06:00 after lock (midnight) (= that date's 00:00 + 30h, pet wake-up time).
// Idempotency key = existence of that pet's comment (no re-commenting) — if the app was off, this polling backfills after boot (oldest date first).
let diaryCommentAt = 0, diaryCommentBusy = false;
function ownerCommentDue() {
    const now = Date.now();
    return Object.keys(diaryData).filter((d) => {
        const o = (diaryData[d] || {}).owner;
        if (!o || !o.text) return false;
        if (now < new Date(d + 'T00:00:00').getTime() + 30 * 3600000) return false;   // Before 06:00 the next day
        return pets.some((p) => !(o.comments || []).some((c) => c.pet === p.name));
    }).sort()[0] || null;
}
async function runOwnerComments(d) {
    diaryCommentBusy = true;
    let allOk = true;
    try {
        for (const p of pets) {   // Sequential — so LLM calls don't overlap (diary grammar)
            const o = (diaryData[d] || {}).owner;
            if (!o || (o.comments || []).some((c) => c.pet === p.name)) continue;
            try {
                const res = await fetch('/api/world_diary_comment', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ pet: p.name, date: d }),
                });
                if (!res.ok) { allOk = false; continue; }
                const c = await res.json();
                (o.comments = o.comments || []).push({ pet: c.pet, text: c.text, ts: c.ts });
            } catch (e) { allOk = false; }
        }
        const o = (diaryData[d] || {}).owner;
        if (o && pets.every((p) => (o.comments || []).some((c) => c.pet === p.name))) {
            logWorldEvent('펫들이 주인 일기를 읽고 댓글을 남겼다 💬');
            renderDiary();
        }
    } finally {
        diaryCommentBusy = false;
        diaryCommentAt = Date.now() + (allOk ? 60000 : 600000);   // Failure (LLM down, etc.) = 10 min backoff
    }
}
function maybeAutoDiary() {
    if (!diaryCommentBusy && Date.now() >= diaryCommentAt && pets.length) {
        diaryCommentAt = Date.now() + 60000;
        const due = ownerCommentDue();
        if (due) runOwnerComments(due);
    }
    if (Date.now() < diaryAutoAt || !pets.length) return;
    diaryAutoAt = Date.now() + 60000;
    const isNight = currentHour() >= 22.05;
    const targetDay = isNight ? new Date() : new Date(Date.now() - 86400000);
    const target = localDateStr(targetDay);
    try { if (localStorage.getItem('world-diary-auto') === target) return; } catch (e) {}
    if (!dayEventsText(targetDay)) {
        // Yesterday's share can't get more events — finalize as an empty day. Today's share stays open until midnight.
        if (!isNight) try { localStorage.setItem('world-diary-auto', target); worldSync('world-diary-auto'); } catch (e) {}
        return;
    }
    (async () => {
        diaryAutoAt = Infinity;   // No re-entry while writing
        for (const p of pets) await writeDiary(p.name, false, true, targetDay);   // Sequential — so LLM calls don't overlap
        const ok = pets.some((p) => (diaryData[target] || {})[p.name]);   // writeDiary swallows failures — judge by the result (the owner entry is not a pet diary — consuming the flag on a day with only an owner diary means the pet diary is never written)
        if (ok) {
            try { localStorage.setItem('world-diary-auto', target); worldSync('world-diary-auto'); } catch (e) {}
            logWorldEvent(isNight ? '오늘의 그림일기를 썼다 📔' : '어제 못 쓴 그림일기를 마저 썼다 📔');
        }
        diaryAutoAt = Date.now() + (ok ? 60000 : 600000);   // Failure = retry in 10 min
    })();
}
function bindZoomBtn(b, dir) {
    b.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        camZoom(dir < 0 ? 0.8 : 1.25);
        heldZoom = dir;
        try { b.setPointerCapture(e.pointerId); } catch (err) {}
    });
    const stop = () => { heldZoom = 0; };
    b.addEventListener('pointerup', stop);
    b.addEventListener('pointercancel', stop);
    b.addEventListener('lostpointercapture', stop);
}
const buildBtn = dockBtn('🔨', '공사 모드 — 사물 옮기기');
