// 🐥🐕 Pet shortcuts: press to fly the camera to that pet (follow cam) and start control immediately — pressing the same button
// again releases. Pressing while controlling another pet switches to that pet.
function possessByName(name) {
    const p = pets.find((q) => q.name === name);
    if (!p) return;
    if (possessed === p) { escapeAction(); return; }   // Toggle off (includes menu/panel cleanup)
    if (buildMode) setBuildMode(false);                // If in construction mode, save, exit, then control
    possessPet(p);
}
// 👀 Spectate mode: unlike control, doesn't touch ai.state so the pet's autonomous behavior continues as-is. Camera only follows.
// Each press cycles: (none)→pet1→pet2→…→off. Mutually exclusive with possessed (pressing while controlling releases control).
function startSpectate(p) {
    if (possessed) releasePossession();   // Can't coexist with control — drop control and switch to spectating
    spectating = p;
    controlHint.textContent = `👀 ${p.name === 'chick' ? '병아리' : '강아지'} 시점 — 자율행동 그대로 (👀 다시 눌러 전환/해제)`;
    controlHint.style.display = 'block';
}
function stopSpectate() {
    spectating = null;
    if (!possessed) controlHint.style.display = 'none';
}
function spectateNext() {
    if (buildMode) setBuildMode(false);
    const order = pets;   // [chick, puppy]
    // Current position: -1 if controlling or not spectating (next = first pet), otherwise the spectated index
    const cur = (possessed || !spectating) ? -1 : order.indexOf(spectating);
    const next = cur + 1;
    if (next >= order.length) stopSpectate();   // After the last = off
    else startSpectate(order[next]);
}
