// ---- Dock cleanup (plan A): resident = 📷·🐥·🐕·(🎣 only while possessing)·2 drawers·zoom — 12 → 6~7 resident.
// Drawers unfold horizontally to the left (saves vertical space), only one open, auto-collapse on child click or 4s without input.
// State shows as a badge even when collapsed: ⚙️ green dot = construction/power-save on, 📖 red dot = new fish species in the encyclopedia.
let dockOpenDrawer = null;
function dockDrawer(emoji, title, children) {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex; flex-direction:row; align-items:center; gap:6px;';
    const panel = document.createElement('div');
    panel.style.cssText = 'display:flex; flex-direction:row; gap:6px; overflow:hidden; max-width:0; opacity:0; transition:max-width 0.26s ease, opacity 0.2s ease;';
    for (const c of children) panel.appendChild(c);   // Move from directly under dockUI into the drawer
    const launcher = dockBtn(emoji, title);
    row.appendChild(panel);
    row.appendChild(launcher);
    const d = { row, launcher, panel, open: false, timer: 0 };
    const setOpen = (v) => {
        d.open = v;
        panel.style.maxWidth = v ? `${children.length * (IS_TOUCH ? 54 : 46) + 8}px` : '0';
        panel.style.opacity = v ? '1' : '0';
        launcher.style.background = v ? 'rgba(70,76,92,0.92)' : 'rgba(30,32,40,0.88)';
        clearTimeout(d.timer);
        if (v) {
            if (dockOpenDrawer && dockOpenDrawer !== d) dockOpenDrawer.setOpen(false);   // Only one open
            dockOpenDrawer = d;
            d.timer = setTimeout(() => setOpen(false), 4000);   // Auto-collapse
        } else if (dockOpenDrawer === d) dockOpenDrawer = null;
    };
    d.setOpen = setOpen;
    launcher.onclick = () => setOpen(!d.open);
    panel.addEventListener('click', () => setTimeout(() => setOpen(false), 120));   // Collapse after running a child
    return d;
}
