    if (p.ai.state !== 'idle' && p.ai.state !== 'walk') return 'busy';
    if ((fishing && fishing.p === p) || (aiFishing && aiFishing.p === p)) return 'busy';
    const pr = PROPS.find((q) => q.type === 'radio');
    if (!pr) return 'busy';
