                scal.translate(0, cy, -R * 0.24);                                     // The upper part of the bowl is shallow, so the meat also moves toward the opening
                const mg = bakeGrad(scal, 0xe89a4e, 0xa8541a, { curve: 1.25 });        // ⚠️ Bake the gradient after rotation and translation (bakeGrad is y-axis based). glossParts blows bright orange out into a white ball — tone the color down (measured)
                const mc = mg.attributes.color, mp = mg.attributes.position, mtmp = new THREE.Color();
