                    const dx = mp.getX(i), dy = mp.getY(i) - cy, rr2 = Math.hypot(dx, dy);
                    mtmp.setRGB(mc.getX(i), mc.getY(i), mc.getZ(i));
                    mtmp.offsetHSL(0, 0, Math.sin(Math.atan2(dy, dx) * 13) * 0.075 - Math.max(0, rr2 / MR - 0.72) * 0.42);
