        skStick(0.175, !raw);
        const MR = 0.0135, MH = 0.0195;                 // Plump (user confirmed) — small ones make the skewer look skimpy
        const slots = [0.068, 0.0905, 0.113];           // 3mm gap — spaced just enough not to touch
