        if (!q) return;
        const qx = ROCKET.x + ux * 1.5 - uz * side * 0.5;
        const qz = ROCKET.z + uz * 1.5 + ux * side * 0.5;
        q.mover.position.set(qx, poiSurfaceY(poi, qx, qz), qz);
        q.mover.rotation.set(0, Math.atan2(ux, uz), 0);
        q.swimming = false;
