    showToast('🚀 재탑승 — 이륙!');
    logWorldEvent(ROCKET.poi && ROCKET.poi.id === 'moon' ? '별똥호가 달에서 이륙했다 🌕' : '별똥호가 정거장을 떠났다 🛰️');
