        FERRY.route = route;
        FERRY.u = 0;
        FERRY.mode = 'sail';
        FERRY.easeT = 0;
        ferryHorn();
        logWorldEvent(`${petKo(rider)}가 통통호에 올랐다 — 붕— 출항!${ferryRide.friend ? ' (절친도 함께)' : ''} ⛴️`);
        if (!isAI) showToast('⛴️ 붕— 출항! 모래섬 잔교에 정박해요 (정박 중 ⌘ = 하차 · 항해 중 ⌘ = 퐁당)');
