            if (Math.hypot(sp.x - p.mover.position.x, sp.z - p.mover.position.z) < 15) return true;
            sp.mesh.traverse((o) => { if (o.isMesh) o.geometry.dispose(); });
            fruitLayer.remove(sp.mesh);
