    tipPivot.position.y = 0.2;
    const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.01, 0.22, 6), M(0xb08a60, { map: woodTex }));
    tip.position.y = 0.11;
    tipPivot.add(tip);
