            g.fillStyle = k % 2 ? `rgba(78,64,86,${0.26 + fcHash(k + 3) * 0.14})` : `rgba(92,80,66,${0.24 + fcHash(k + 5) * 0.14})`;
            g.fill(); g.restore();
